// host until AF-CTR-09. Nothing here grants anything.

/** The kind of a method the Worker admits: one unary reply, or a server stream. */
export type RouteKind = "unary" | "serverStream";
/** anonymous: no credential is read or forwarded; session: bearer or origin-bound cookie, checked again by the host. */
export type RouteAuth = "anonymous" | "session";

export interface ApiRoute {
  /** The method path without the owned /api prefix: /package.Service/Method. */
  readonly path: string;
  readonly kind: RouteKind;
  readonly auth: RouteAuth;
  /** Bound of the whole request body, frame header included. Unary and server-streaming requests are one message. */
  readonly maxRequestBytes: number;
  /** Bound of one response frame. */
  readonly maxFrameBytes: number;
  /** Bound of a whole unary response (buffered); a stream has no total bound, only its lifetime. */
  readonly maxUnaryResponseBytes: number;
  /** Cap of the RPC deadline (unary) or of the stream's lifetime (server stream). */
  readonly maxDurationMs: number;
  /** The Container instance (Durable Object name) that serves the method. */
  readonly instance: string;
  /**
   * The request message starts with a RequestMeta (field 1, wire registry 04). Only then does the edge read the client's
   * correlation id from it; a method whose field 1 means something else (the Hello name) is never interpreted.
   */
  readonly requestMeta: boolean;
}

/** A switchable surface of the center (AF-CTR-03; AF-PLAT-01 owns the activation variable's other names). */
export type Surface = "identity";

/** A method of a switchable surface. */
export interface SurfaceRoute extends ApiRoute {
  readonly surface: Surface;
}

/** The surface names, in registration order; FLAGSHIP_SURFACES lists them comma-separated and exactly. */
export const surfaceNames: readonly Surface[] = ["identity"];
/** The header the Worker sets to the client's address (from cf-connecting-ip) on every surface call. */
export const clientIpHeader = "x-arcforges-client-ip";
/**
 * The gRPC-Web body (one reply frame and the OK status trailer) answering a call of a disabled surface: the domain refusal
 * STATE/not_activated naming the surface, without a correlation id (the center's own reply carries one). Base64.
 */
export const notActivatedReplies: Readonly<Record<Surface, string>> = {
  identity:
    "AAAAAEIaQAoNbm90X2FjdGl2YXRlZBAGGhllcnJvci5zdGF0ZS5ub3RfYWN0aXZhdGVkIgIIASgBOgwiChIIaWRlbnRpdHmAAAAAEGdycGMtc3RhdHVzOiAwDQo=",
};
/**
 * The gRPC-Web body answering a surface call over the edge rate limit: RESOURCE/rate_limited (limit "edge"), retry after time.
 * A template: the Worker writes the retry instant (the refusal's time rounded up to the second, plus the edge period) into
 * the instant seconds at each offset (retry.retry_at and limit.recovery_at). Base64.
 */
export const rateLimitedReply =
  "AAAAAFMaUQoMcmF0ZV9saW1pdGVkEAcaG2Vycm9yLnJlc291cmNlLnJhdGVfbGltaXRlZCIMCAMSCAiAgICAQBAAKAE6EhIQCgRlZGdlIggIgICAgEAQAIAAAAAQZ3JwYy1zdGF0dXM6IDANCg==";
/** The byte offsets of the template's instant seconds (zigzag varints of a fixed width). */
export const rateLimitedReplyInstantOffsets: readonly number[] = [59, 81];
/** The width of each instant's seconds: five varint bytes hold every instant from 1974 to 2514. */
export const rateLimitedReplyInstantBytes = 5;
/** The period of the surface rate limit in seconds (wrangler.json IDENTITY_RATE_LIMITER simple.period). */
export const edgeRateLimitPeriodSeconds = 60;
/** The network that keys an IPv6 client at the edge rate limits; an IPv4 client is keyed by its whole address. */
export const edgeIpv6PrefixBits = 64;
/**
 * How long the Container class waits for a center started under another Worker version's settings to stop on SIGTERM: the
 * center's shutdown bound and a margin (AF-CTR-03).
 */
export const staleCenterStopMs = 6000;
/** How long it then waits for the kill before it refuses the request as a start failure. */
export const staleCenterKillMs = 4000;
/** How often it looks whether the center stopped. */
export const centerStopPollMs = 100;

